# Construct PG(2,3) - the projective plane of order 3
# Points are 1D subspaces of GF(3)^3
# Lines are 2D subspaces of GF(3)^3

from itertools import combinations

# GF(3) = {0, 1, 2}
# Points of PG(2,3): non-zero vectors (a,b,c) in GF(3)^3 up to scalar multiple
# Representatives: first non-zero coordinate is 1

def normalize(v, q=3):
    """Normalize a projective point - first nonzero coord = 1"""
    for i in range(len(v)):
        if v[i] != 0:
            inv = pow(int(v[i]), q-2, q)  # modular inverse
            return tuple((x * inv) % q for x in v)
    return None

# Generate all points of PG(2,3)
points = []
seen = set()
for a in range(3):
    for b in range(3):
        for c in range(3):
            if (a, b, c) == (0, 0, 0):
                continue
            n = normalize((a, b, c))
            if n not in seen:
                seen.add(n)
                points.append(n)

print(f"Number of points: {len(points)}")
print("Points:", points)

# Lines of PG(2,3): sets of points satisfying a*x + b*y + c*z = 0 (mod 3)
# Each line is determined by a normal vector [a:b:c]

